KNIGHT_JUMPS = [(1, 2), (2, 1), (2, -1), (1, -2),
                (-1, -2), (-2, -1), (-2, 1), (-1, 2)]

def on_board(sq):
    return 0 <= sq[0] < 8 and 0 <= sq[1] < 8

# dict version: behavior lives in free functions that take the dict
def knight_moves(piece):
    return sorted((piece["file"] + dx, piece["rank"] + dy)
                  for dx, dy in KNIGHT_JUMPS
                  if on_board((piece["file"] + dx, piece["rank"] + dy)))

piece = {"kind": "knight", "file": 3, "rank": 3}
print("dict version moves:", knight_moves(piece))
print("dict itself carries behavior?", "moves" in piece)

# class version: the rule travels with the piece
class Knight:
    def __init__(self, file, rank):
        self.file = file
        self.rank = rank
    def moves(self):
        return sorted((self.file + dx, self.rank + dy)
                      for dx, dy in KNIGHT_JUMPS
                      if on_board((self.file + dx, self.rank + dy)))
    def __repr__(self):
        return f"Knight(file={self.file}, rank={self.rank})"

