# A bag whose subclass counts successful adds by overriding add()
class Bag:
    def __init__(self):
        self._items = []
    def add(self, item):
        self._items.append(item)
    def add_all(self, items):
        for item in items:
            self.add(item)          # v1: routes through add()
    def __len__(self):
        return len(self._items)

class CountingBag(Bag):
    def __init__(self):
        super().__init__()
        self.added = 0
    def add(self, item):
        self.added += 1
        super().add(item)

bag = CountingBag()
bag.add_all(["a", "b", "c"])
print("v1 base: items =", len(bag), "| counted adds =", bag.added)

# v2 of the base: add_all is 'optimized' to bypass add()
class BagV2:
    def __init__(self):
        self._items = []
    def add(self, item):
        self._items.append(item)
    def add_all(self, items):
        self._items.extend(items)   # faster — and silently skips the override
    def __len__(self):
        return len(self._items)

class CountingBagV2(BagV2):
    def __init__(self):
        super().__init__()
        self.added = 0
    def add(self, item):
        self.added += 1
        super().add(item)

bag2 = CountingBagV2()
bag2.add_all(["a", "b", "c"])
print("v2 base: items =", len(bag2), "| counted adds =", bag2.added)
print("invariant holds v1:", len(bag) == bag.added,
      "| invariant holds v2:", len(bag2) == bag2.added)

