# The fix: a hash computed from exactly the fields __eq__ compares
class HashablePoint:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __eq__(self, other):
        return isinstance(other, HashablePoint) and (self.x, self.y) == (other.x, other.y)
