import json, csv, io

class JsonExporter:
    def export(self, rows):
        return json.dumps(rows, sort_keys=True)

class CsvExporter:
    def export(self, rows):
        buf = io.StringIO()
        writer = csv.DictWriter(buf, fieldnames=["name", "qty"])
        writer.writeheader()
        writer.writerows(rows)
        return buf.getvalue().strip().splitlines()

def publish(exporter, rows):
    # knows nothing about either class — only that .export(rows) exists
    return exporter.export(rows)

rows = [{"name": "pen", "qty": 3}, {"name": "pad", "qty": 5}]
print("json:", publish(JsonExporter(), rows))
print("csv lines:", publish(CsvExporter(), rows))
print("bases:", JsonExporter.__bases__, CsvExporter.__bases__)

