# Plugins are duck-typed: they need name() and run(text) -> str.
class UpperPlugin:
    def name(self): return "upper"
    def run(self, data): return data.upper()

class ReversePlugin:
    def name(self): return "reverse"
    def run(self, data): return data[::-1]

class BrokenPlugin:
    def name(self): return "broken"
    # no run() at all

REGISTRY = [UpperPlugin(), ReversePlugin(), BrokenPlugin()]

def check_plugin(p):
    problems = []
    if not callable(getattr(p, "name", None)):
        problems.append("missing name()")
    if not callable(getattr(p, "run", None)):
        problems.append("missing run()")
    if problems:
        return problems
    try:
        out = p.run("ab")
        if not isinstance(out, str):
            return ["run() did not return a string"]
    except Exception as e:
        return [f"run() raised {type(e).__name__}"]
    return []

for p in REGISTRY:
    problems = check_plugin(p)
    label = p.name() if callable(getattr(p, "name", None)) else "?"
    print(label, "->", problems if problems else "OK")

good = [p for p in REGISTRY if not check_plugin(p)]
print("pipeline output:", [p.run("abc") for p in good])

