class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y        # trivial: no parsing, no I/O, no math
    @classmethod
    def from_polar(cls, r, theta_deg):
        rad = math.radians(theta_deg)
        return cls(round(r * math.cos(rad), 2), round(r * math.sin(rad), 2))
    @classmethod
    def from_csv(cls, text):
        row = next(csv.reader(io.StringIO(text)))
