class Color:
    """Flyweight: equal colors are the same object, via a __new__ cache."""
    _cache = {}
    def __new__(cls, name):
        if name in cls._cache:
            return cls._cache[name]
        obj = super().__new__(cls)
        cls._cache[name] = obj
        return obj
    def __init__(self, name):
        self.name = name
    def __repr__(self):
        return f"Color({self.name!r})"

