class IllegalTransition(Exception):
    pass

class Order:
    TRANSITIONS = {
        "placed":    {"pay", "cancel"},
        "paid":      {"ship", "refund"},
        "shipped":   {"deliver"},
        "delivered": set(),
        "cancelled": set(),
        "refunded":  set(),
    }
    NEXT = {"pay": "paid", "cancel": "cancelled", "ship": "shipped",
            "deliver": "delivered", "refund": "refunded"}
    def __init__(self, oid):
        self.oid = oid
        self.state = "placed"
    def do(self, action):
        if action not in self.TRANSITIONS[self.state]:
            raise IllegalTransition(f"cannot {action} from {self.state}")
        self.state = self.NEXT[action]
        return self.state
    def __repr__(self):
        return f"Order({self.oid}, state={self.state})"

o = Order(101)
print("after pay: ", o.do("pay"))
print("after ship:", o.do("ship"))
try:
    o.do("refund")
except IllegalTransition as e:
    print("refused:", e)
print("final:", o)

