class Spec:
    """A composable predicate object."""
    def __init__(self, fn, label):
        self._fn = fn
        self.label = label
    def matches(self, item):
        return self._fn(item)
    def __and__(self, other):
        return Spec(lambda it: self.matches(it) and other.matches(it),
                    f"({self.label} AND {other.label})")
    def __or__(self, other):
        return Spec(lambda it: self.matches(it) or other.matches(it),
                    f"({self.label} OR {other.label})")
    def __repr__(self):
        return f"Spec({self.label})"

