from dataclasses import dataclass

# Book: pure data -> dataclass
@dataclass
class Book:
    title: str
    author: str

# Loan: invariants + a lifecycle -> class
class Loan:
    def __init__(self, book, member, loan_day, due_day):
        if due_day <= loan_day:
            raise ValueError("due day must be after loan day")
        self.book = book
        self.member = member
        self.loan_day = loan_day
        self.due_day = due_day
        self.returned_day = None
    def return_book(self, day):
        if self.returned_day is not None:
            raise ValueError("already returned")
        if day < self.loan_day:
            raise ValueError("cannot return before the loan day")
        self.returned_day = day
    def __repr__(self):
        state = "out" if self.returned_day is None else f"returned day {self.returned_day}"
        return f"Loan({self.book.title!r} to {self.member}, {state})"

# Catalog: a lookup, not an object -> dict + functions
